package ai.decisionos.aside;
import java.io.*;import java.util.zip.*;import org.xmlpull.v1.*;
/** Bounded local text preview; never expands archives on disk or resolves external XML entities. */
final class CompanionDocumentPreview {
 static String read(InputStream input)throws Exception{StringBuilder out=new StringBuilder();int total=0,parts=0;try(ZipInputStream zip=new ZipInputStream(input)){ZipEntry entry;int entries=0;while((entry=zip.getNextEntry())!=null){if(++entries>2000)throw new IOException("파일 항목이 너무 많아요.");String name=entry.getName();boolean selected=name.equals("word/document.xml")||name.matches("Contents/section[0-9]{1,2}\\.xml");if(selected&&++parts>20)throw new IOException("문서가 너무 길어요.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] block=new byte[4096];int n;while((n=zip.read(block))!=-1){total+=n;if(total>8388608)throw new IOException("미리보기 한도를 초과했어요.");if(selected){if(bytes.size()+n>2097152)throw new IOException("본문 미리보기 한도를 초과했어요.");bytes.write(block,0,n);}}if(!selected)continue;String xml=bytes.toString("UTF-8");if(xml.contains("<!DOCTYPE")||xml.contains("<!ENTITY"))throw new IOException("지원하지 않는 XML이에요.");XmlPullParser parser=XmlPullParserFactory.newInstance().newPullParser();parser.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);parser.setInput(new StringReader(xml));boolean text=false;int event;while((event=parser.next())!=XmlPullParser.END_DOCUMENT){String tag=parser.getName();if(event==XmlPullParser.START_TAG&&"t".equals(tag))text=true;else if(event==XmlPullParser.TEXT&&text){out.append(parser.getText());if(out.length()>200000)throw new IOException("미리보기 텍스트가 너무 길어요.");}else if(event==XmlPullParser.END_TAG){if("t".equals(tag))text=false;if("p".equals(tag)||"tr".equals(tag))out.append('\n');if("tc".equals(tag))out.append("  ");}}}}if(parts==0)throw new IOException("DOCX/HWPX 본문을 찾지 못했어요.");return out.toString().trim();}
}
